import{_ as t,o as a,c as i,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy art and UI brief","description":"Owners: Luis (art), Miguel (UI), Sherwin (experience). October 12, 2026.","frontmatter":{"title":"Chainy art and UI brief","description":"Owners: Luis (art), Miguel (UI), Sherwin (experience). October 12, 2026.","source":"docs/design/design-brief.md","category":"Game & system design","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/design-brief.md","filePath":"content/docs/design/design-brief.md"}'),n={name:"content/docs/design/design-brief.md"};function s(o,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-art-and-ui-brief">Chainy art and UI brief<a class="header-anchor" href="#chainy-art-and-ui-brief" aria-label="Link to this section">​</a></h1><p>Owners: Luis (art), Miguel (UI), Sherwin (experience). October 12, 2026.</p><h2 id="visual-direction">Visual direction<a class="header-anchor" href="#visual-direction" aria-label="Link to this section">​</a></h2><p>Keep the approved rounded, friendly 3D style: blue-haired explorer in yellow, screen-faced robots and compact island scenery. The two supplied Chainy images remain art references:</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-01.png" alt="Chainy visual reference"></p><p><a href="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-02.png">Second visual reference</a>. Their old gameplay details, counts and screen layouts are not current requirements. The BlockForge image and previous generated gameplay diagrams are historical.</p><h2 id="small-production-package">Small production package<a class="header-anchor" href="#small-production-package" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Person</th><th>Deliver</th><th>Review</th></tr></thead><tbody><tr><td>Luis</td><td>Reusable character/robot/prop assets, a compact level kit, mode icons and simple feedback effects</td><td>Christian checks import/performance; Miguel checks screen fit</td></tr><tr><td>Miguel</td><td>Profile entry, menu, movement/interaction prompts, Quiz/Wordle/BlockMatch UI, results, pause and save-error feedback</td><td>Sherwin checks clarity; Christian checks behavior</td></tr><tr><td>Sherwin</td><td>Player journey, approved mode rules, screen priorities and learning purpose</td><td>Sean checks instructional wording</td></tr><tr><td>Sean</td><td>Final instructions, definitions, answer explanations and captions</td><td>Sherwin and Christian</td></tr></tbody></table><p>Use the existing models reported by Christian before requesting replacement art. Make a representative sample first, then complete only the approved inventory. Luis supplies editable files, export settings, naming and source/license notes; do not invent polygon/texture budgets before testing the sample.</p><h2 id="readability-and-handoff">Readability and handoff<a class="header-anchor" href="#readability-and-handoff" aria-label="Link to this section">​</a></h2><p>Show the objective, available action and result clearly. Pair color with text/icons. Keep essential content usable with audio muted. Test on the smallest available target phone.</p><p>Deliver assets/screens with a preview, source path, import notes, intended use and known gaps. Christian owns shared scenes; Luis and Miguel hand over assets/prefabs without overwriting integration work.</p><p>CH-10 owns the reusable kit; CH-26 owns screens. The integrated build is targeted for October 30; October 31–November 2 is protected testing time before the fixed November 3–6 beta.</p></div>',1)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
